from __future__ import annotations

from pydantic import Field
from typing_extensions import TypedDict

from ..core import SdkBaseModel


class FraudCheckResult(SdkBaseModel):
    account_score: int = Field(alias="accountScore")
    """The fraud score generated by the risk check."""

    check_id: int = Field(alias="checkId")
    """The ID of the risk check."""

    name: str
    """The name of the risk check."""


class FraudCheckResultDict(TypedDict):
    account_score: int
    check_id: int
    name: str
